        'ui-shift-evening-label': dict.shift_evening_label || "🌙 شعبێن دەواما ئێڤارێ (المسائي):",
        'ui-detected-sections-label': dict.detected_sections_label || "الشُعب المتوفرة (انقر لتعيين نوع الدوام):",
